+AskQuestion _question({
+  String text = 'Proceed with the plan?',
+  List<AskOption> options = const [
+    AskOption(label: 'Yes'),
+    AskOption(label: 'No', description: 'Stop here'),
+    AskOption(label: 'Ask later'),
